def anidar(plano: dict) -> dict:
    """
    Recorre un diccionario plano y anida las claves con puntos en un diccionario anidado.

    Ejemplo: {'a.b': 1} -> {'a': {'b': 1}}

    Args:
        plano: Un diccionario plano con claves que pueden contener puntos.

    Returns:
        Un diccionario anidado con las claves separadas por puntos.
    """
    anidado = {}
    for clave, valor in plano.items():
        if '.' in clave:
            partes = clave.split('.')
            anidado[partes[0]] = anidar({partes[1]: valor})
        else:
            anidado[clave] = valor
    return anidado


