def comprimir(s: str) -> str:
    """Aplica run-length encoding a una string.

    Caracteres que aparecen una sola vez se representan como 'c1'.
    """
    if not s:
        return ""

    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    result = []
    for char, count in counts.items():
        if count == 1:
            result.append(f"{char}1")
        else:
            result.append(f"{char}{count}")

    return "".join(result)

def formatear_bytes(n: int) -> str:
    """
    Convierte un número de bytes a texto legible usando múltiplos de 1024
    y las unidades B, KB, MB, GB.

    Regla:
      - B: sin decimales
      - KB, MB, GB: con decimales
    """
    if n < 0:
        return "Error: valor negativo"

    if n == 0:
        return "0 B"

    if n < 1024:
        return f"{n} B"

    if n < 1024 * 1024:
        return f"{n / 1024:.1f} KB"

    if n < 1024 * 1024 * 1024:
        return f"{n / (1024 * 1024):.1f} MB"

    return f"{n / (1024 * 1024 * 1024):.1f} GB"

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split('&'):
        if '=' in part:
            key, value = part.split('=', 1)
            result[key] = value
    return result

def contar_islas(grid: list[list[int]]) -> int:
    """
    Recibe una matriz de 0 y 1 y devuelve el número de grupos de 1 conectados.
    Dos celdas son conectadas si comparten un lado (arriba, abajo, izquierda, derecha).
    """
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]

    def dfs(r: int, c: int) -> None:
        visited[r][c] = True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1 and not visited[nr][nc]:
                dfs(nr, nc)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                dfs(r, c)
                count += 1
    return count

