def sumar_romanos(a: str, b: str) -> str:
    """
    Suma dos números romanos y devuelve el resultado en romano.

    Args:
        a: String representando un número romano.
        b: String representando un número romano.

    Returns:
        String representando la suma de a y b en romano.
    """
    def valor_romano(s: str) -> int:
        """Convierte un string romano a entero."""
        valores = {
            'I': 1, 'V': 5, 'X': 10,
            'L': 50, 'C': 100, 'D': 500, 'M': 1000
        }
        total = 0
        for i in range(len(s) - 1, -1, -1):
            if i + 1 < len(s) and s[i] == s[i + 1]:
                total += valores[s[i]] * 2
                i += 1
            else:
                total += valores[s[i]]
        return total

    def romano_de_ental(a: int) -> str:
        """Convierte un entero a string romano."""
        if a == 0:
            return ""
        valores = {
            'I': 1, 'V': 5, 'X': 10,
            'L': 50, 'C': 100, 'D': 500, 'M': 1000
        }
        resultado = []
        for i in range(len(valores)):
            if a >= valores[i]:
                resultado.append(valores[i])
                a -= valores[i]
            else:
                break
        return ''.join(str(x) for x in resultado)

    a_val = valor_romano(a)
    b_val = valor_romano(b)
    resultado = a_val + b_val

    if resultado == 0:
        return ""
    return romano_de_ental(resultado)

def con_reintentos(fn, veces):
    """
    Ejecuta fn() y, si lanza una excepcion, la reintenta hasta 'veces' intentos en total.
    Si todos fallan, vuelve a lanzar la ultima excepcion.
    Devuelve el resultado si alguno funciona.

    Args:
        fn: Función que puede lanzar excepciones.
        veces: Número máximo de intentos.

    Returns:
        El resultado de la primera ejecución exitosa de fn().
    """
    for i in range(veces):
        try:
            return fn()
        except Exception as e:
            if i == veces - 1:
                raise e
            # Reintentar la misma función
            fn()
    raise RuntimeError("No se pudo obtener un resultado después de " + str(veces) + " intentos.")
